/**
 * Narration clips: a spoken line id → a file under `public/audio/`.
 *
 * Generated by the offline Chatterbox render, which is not part of this track (plan D1). It stays
 * empty here on purpose: with no clip, the narration factory falls back to the system voice
 * (plan D2). The shape is in place so the render can drop in without touching the app.
 */
export const audioManifest: Readonly<Record<string, string>> = {};

/** The clip for a line, or `undefined` when it has not been rendered yet. */
export function findClip(lineId: string): string | undefined {
  return audioManifest[lineId];
}
